// ESM loader: resolve bare directory imports to index.js.
// Needed on Node 18+ where --experimental-specifier-resolution=node was removed.
import { stat } from 'node:fs/promises';
import { pathToFileURL, fileURLToPath } from 'node:url';

export async function resolve(specifier, context, nextResolve) {
  const result = await nextResolve(specifier, context).catch(() => null);
  if (result) return result;

  // Only attempt to fix relative specifiers that look like directories.
  if (!specifier.startsWith('.')) return nextResolve(specifier, context);

  const base = context.parentURL ? fileURLToPath(new URL(specifier, context.parentURL)) : specifier;
  const candidate = `${base}/index.js`;
  try {
    await stat(candidate);
    return { url: pathToFileURL(candidate).href, shortCircuit: true };
  } catch {
    return nextResolve(specifier, context);
  }
}

