// ESM loader: resolve bare directory imports and extension-less .js imports.
// Needed on Node 18+ where --experimental-specifier-resolution=node was removed.
import { stat } from 'node:fs/promises';
import { pathToFileURL, fileURLToPath } from 'node:url';

async function exists(p) {
  try { await stat(p); return true; } catch { return false; }
}

export async function resolve(specifier, context, nextResolve) {
  // Only intercept relative specifiers.
  if (!specifier.startsWith('.')) return nextResolve(specifier, context);

  if (context.parentURL) {
    const base = fileURLToPath(new URL(specifier, context.parentURL));

    // 1. Try appending /index.js (directory import).
    if (await exists(`${base}/index.js`)) {
      return { url: pathToFileURL(`${base}/index.js`).href, shortCircuit: true };
    }

    // 2. Try appending .js (extension-less import).
    if (await exists(`${base}.js`)) {
      return { url: pathToFileURL(`${base}.js`).href, shortCircuit: true };
    }
  }

  return nextResolve(specifier, context);
}

